import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def count_divisors(n):
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            count += 1
            if i*i != n:
                count += 1
    return count

def check_n(n):
    divs = get_divisors(n)
    if len(divs) < 5:
        return None

    # a=2nd, b=3rd, c=5th smallest divisors
    try:
        a = divs[1]
        b = divs[2]
        c = divs[4]
    except IndexError:
        # Should not happen if len(divs) >= 5
        return None

    # Check the condition n = ab + ac + bc
    if n == a * b + a * c + b * c:
        tau_n = len(divs)
        return {
            'n': n,
            'tau(n)': tau_n,
            'a': a,
            'b': b,
            'c': c
        }
    return None

# Search for n >= 1000, focusing on tau(n) outside {8, 9}
solutions_outside_8_9 = []
# Limiting the search range for reasonable execution time
SEARCH_LIMIT = 3000 

print(f"Starting search for n >= 1000 up to {SEARCH_LIMIT}...")

for n in range(1000, SEARCH_LIMIT + 1):
    result = check_n(n)
    if result:
        tau = result['tau(n)']
        if tau not in [8, 9]:
            solutions_outside_8_9.append(result)

if solutions_outside_8_9:
    print("\n--- Solutions Found with tau(n) not in {8, 9} ---")
    for sol in solutions_outside_8_9:
        print(f"n={sol['n']}, tau(n)={sol['tau(n)']}, a={sol['a']}, b={sol['b']}, c={sol['c']}")
else:
    print("\nNo solutions found in the range [1000, 3000] with tau(n) not in {8, 9}.")

# Check for other structures like tau(n) = 6
# n=p^2 q. Smallest divisors: 1, p, q, p^2, pq.
# a=p, b=q, c=pq.
# n = pq + p(pq) + q(pq) = pq + p^2q + pq^2 = pq(1 + p + q)
# Since n = p^2 q, we must have p^2 q = pq(1 + p + q)
# p = 1 + p + q
# 0 = 1 + q. Impossible since q > 0.
# This confirms the structure p^2 q is impossible if the divisors are ordered p, q, pq.
# The structure needs careful verification, but the general search covers it.

def get_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

solutions = {
    36: (2, 3, 6),
    56: (2, 4, 8),
    135: (3, 5, 15),
    231: (3, 7, 21),
    351: (3, 9, 27),
    455: (5, 7, 35),
    663: (3, 13, 39),
    935: (5, 11, 55)
}

verification_results = {}

for n, (a, b, c) in solutions.items():
    divs = get_divisors(n)

    # 1. Confirm a, b, c are the 2nd, 3rd, and 5th smallest divisors
    if len(divs) >= 5 and divs[1] == a and divs[2] == b and divs[4] == c:
        div_check = "PASS"
    else:
        div_check = "FAIL (Divisor mismatch)"

    # 2. Verify the equation n = ab + ac + bc
    lhs = a * b + a * c + b * c
    eq_check = "PASS" if lhs == n else f"FAIL (Expected {n}, got {lhs})"

    verification_results[n] = {
        "a": a,
        "b": b,
        "c": c,
        "div_check": div_check,
        "eq_check": eq_check
    }

# Print results in a readable format
for n, res in verification_results.items():
    print(f"--- n={n} ---")
    print(f"Divisor Check: {res['div_check']}")
    print(f"Eq Check: {res['eq_check']}")
    print(f"Divisors: {get_divisors(n)}")

